  // 处理数字、布尔、字符串三类输入

}

console.log(toNumber('42'));

exercise.solution:
function toNumber(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'string') {
    var s = value.trim();
    if (s === '') return null;
    var n = Number(s);
    if (isNaN(n)) return null;
    return n;
  }
  return null;
}

console.log(toNumber('42'));
console.log(toNumber('abc'));

