exercise.solution:
function initials(fullName) {
  if (fullName === '') return '';
  var words = fullName.trim().split(' ');
  var out = [];
  for (var i = 0; i < words.length; i++) {
    out.push(words[i].charAt(0).toUpperCase());
  }
  return out.join('.');
}

console.log(initials('judy alvarez'));

