function grade(score) {
  if (typeof score !== 'number' || isNaN(score) || score < 0 || score > 100) {
    return 'INVALID';
  }
  if (score >= 90) return 'S';
  if (score >= 75) return 'A';
  if (score >= 60) return 'B';
  return 'F';
}

