}

console.log(JSON.stringify(chunk([1, 2, 3, 4, 5], 2)));

exercise.solution:
function chunk(values, size) {
  if (size < 1) return [];
  var out = [];
  for (var i = 0; i < values.length; i += size) {
    out.push(values.slice(i, i + size));
  }
  return out;
}

console.log(JSON.stringify(chunk([1, 2, 3, 4, 5], 2)));

